import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { emptyWorkspace, migrateWorkspace, workspaceSchema } from '../../domain/model';
export const DEFAULT_PREFS = {
    window: { x: null, y: null, width: 1440, height: 960 },
    sidebarWidth: 244,
    historyDbPath: null,
    persistRawComm: false,
    lastWorkspacePath: null,
};
export class WorkspaceService {
    userDataDir;
    workspace = emptyWorkspace();
    filePath = null;
    dirty = false;
    saveTimer = null;
    prefs = { ...DEFAULT_PREFS };
    prefsPath;
    constructor(userDataDir) {
        this.userDataDir = userDataDir;
        this.prefsPath = path.join(userDataDir, 'prefs.json');
        fs.mkdirSync(userDataDir, { recursive: true });
        this.loadPrefs();
    }
    /* ---------------- prefs ---------------- */
    loadPrefs() {
        try {
            if (fs.existsSync(this.prefsPath)) {
                const raw = JSON.parse(fs.readFileSync(this.prefsPath, 'utf-8'));
                this.prefs = {
                    ...DEFAULT_PREFS,
                    ...raw,
                    window: { ...DEFAULT_PREFS.window, ...(raw.window ?? {}) },
                };
            }
        }
        catch {
            this.prefs = { ...DEFAULT_PREFS };
        }
    }
    getPrefs() {
        return this.prefs;
    }
    updatePrefs(patch) {
        this.prefs = { ...this.prefs, ...patch, window: { ...this.prefs.window, ...(patch.window ?? {}) } };
        fs.writeFileSync(this.prefsPath, JSON.stringify(this.prefs, null, 2), 'utf-8');
        return this.prefs;
    }
    /* ---------------- workspace io ---------------- */
    get current() {
        return this.workspace;
    }
    get currentPath() {
        return this.filePath;
    }
    isDirty() {
        return this.dirty;
    }
    newWorkspace() {
        this.workspace = emptyWorkspace();
        this.filePath = null;
        this.dirty = true;
    }
    loadFrom(pathOrNull) {
        const target = pathOrNull ?? this.prefs.lastWorkspacePath;
        if (!target || !fs.existsSync(target))
            return { ok: false, error: 'workspace file not found' };
        try {
            const raw = JSON.parse(fs.readFileSync(target, 'utf-8'));
            this.workspace = migrateWorkspace(raw);
            this.filePath = target;
            this.prefs = this.updatePrefs({ lastWorkspacePath: target });
            this.dirty = false;
            return { ok: true };
        }
        catch (err) {
            return { ok: false, error: String(err) };
        }
    }
    importFromBuffer(text) {
        try {
            const parsed = migrateWorkspace(JSON.parse(text));
            return { ok: true, workspace: parsed };
        }
        catch (err) {
            return { ok: false, error: String(err) };
        }
    }
    adopt(workspace, filePath) {
        this.workspace = workspaceSchema.parse(workspace);
        this.filePath = filePath;
        this.dirty = true;
    }
    set(workspace) {
        this.workspace = workspaceSchema.parse(workspace);
        this.dirty = true;
        this.scheduleAutosave();
        return this.workspace;
    }
    mutate(fn) {
        return this.set(fn(this.workspace));
    }
    /** Atomic write: temp file + rename. Import failures never corrupt the current file. */
    saveTo(target) {
        const dest = target ?? this.filePath;
        if (!dest)
            return { ok: false, error: 'no workspace path; use save-as first' };
        try {
            const tmp = `${dest}.tmp-${process.pid}-${Date.now()}`;
            fs.mkdirSync(path.dirname(dest), { recursive: true });
            fs.writeFileSync(tmp, JSON.stringify(this.workspace, null, 2), 'utf-8');
            fs.renameSync(tmp, dest);
            this.filePath = dest;
            this.dirty = false;
            this.prefs = this.updatePrefs({ lastWorkspacePath: dest });
            return { ok: true, path: dest };
        }
        catch (err) {
            return { ok: false, error: String(err) };
        }
    }
    scheduleAutosave() {
        if (this.saveTimer)
            clearTimeout(this.saveTimer);
        this.saveTimer = setTimeout(() => {
            this.saveTimer = null;
            if (this.dirty && this.filePath)
                this.saveTo();
        }, 800);
    }
    flushAutosave() {
        if (this.saveTimer) {
            clearTimeout(this.saveTimer);
            this.saveTimer = null;
        }
        if (this.dirty && this.filePath)
            this.saveTo();
    }
    exportText() {
        return JSON.stringify(this.workspace, null, 2);
    }
    static defaultWorkspaceDir() {
        return path.join(os.homedir(), 'ModbusStudio');
    }
}
