import fs from 'node:fs';
import path from 'node:path';
import initSqlJs from 'sql.js';
const TEN_GB = 10 * 1024 * 1024 * 1024;
/**
 * History storage backed by sql.js (SQLite compiled to WASM): no native binary, no
 * ABI sensitivity, identical behaviour on every machine. The on-disk file is a
 * standard SQLite database (sql.js export), so external tools can still open it.
 */
export class HistoryStore {
    db;
    dbPath;
    flushTimer = null;
    closed = false;
    constructor(db, dbPath) {
        this.db = db;
        this.dbPath = dbPath;
    }
    static async open(dbPath) {
        // sql.js is a webpack external in main, plain source in tests: probe the layouts.
        const candidates = [
            path.join(__dirname, '..', '..', 'node_modules', 'sql.js', 'dist', 'sql-wasm.wasm'),
            path.join(__dirname, '..', '..', '..', 'node_modules', 'sql.js', 'dist', 'sql-wasm.wasm'),
            path.join(process.cwd(), 'node_modules', 'sql.js', 'dist', 'sql-wasm.wasm'),
        ];
        const wasmPath = candidates.find((c) => fs.existsSync(c));
        if (!wasmPath)
            throw new Error('sql-wasm.wasm not found in any known layout');
        const wasm = fs.readFileSync(wasmPath);
        const SQL = await initSqlJs({ wasmBinary: wasm.buffer.slice(wasm.byteOffset, wasm.byteOffset + wasm.byteLength) });
        fs.mkdirSync(path.dirname(dbPath), { recursive: true });
        const db = fs.existsSync(dbPath) ? new SQL.Database(fs.readFileSync(dbPath)) : new SQL.Database();
        db.run(`
      CREATE TABLE IF NOT EXISTS sessions (
        id TEXT PRIMARY KEY,
        group_id TEXT NOT NULL,
        group_name TEXT NOT NULL,
        start_utc TEXT NOT NULL,
        end_utc TEXT,
        status TEXT NOT NULL,
        schema_json TEXT NOT NULL,
        sample_count INTEGER NOT NULL DEFAULT 0,
        event_count INTEGER NOT NULL DEFAULT 0
      );
      CREATE TABLE IF NOT EXISTS samples (
        session_id TEXT NOT NULL,
        signal_id TEXT NOT NULL,
        t_ms INTEGER NOT NULL,
        value REAL NOT NULL
      );
      CREATE TABLE IF NOT EXISTS events (
        session_id TEXT NOT NULL,
        signal_id TEXT NOT NULL,
        t_ms INTEGER NOT NULL,
        kind TEXT NOT NULL,
        value TEXT NOT NULL
      );
      CREATE TABLE IF NOT EXISTS raw_comm (
        session_id TEXT NOT NULL,
        t_ms INTEGER NOT NULL,
        direction TEXT NOT NULL,
        hex TEXT NOT NULL
      );
      CREATE INDEX IF NOT EXISTS idx_samples ON samples(session_id, signal_id, t_ms);
      CREATE INDEX IF NOT EXISTS idx_events ON events(session_id, t_ms);
    `);
        return new HistoryStore(db, dbPath);
    }
    /* ---------------- persistence ---------------- */
    scheduleFlush() {
        if (this.flushTimer || this.closed)
            return;
        this.flushTimer = setTimeout(() => {
            this.flushTimer = null;
            this.flush();
        }, 1000);
    }
    /** Atomic write: temp file + rename, same guarantee as the workspace file. */
    flush() {
        if (this.closed)
            return;
        const bytes = Buffer.from(this.db.export());
        const tmp = `${this.dbPath}.tmp-${process.pid}-${Date.now()}`;
        fs.writeFileSync(tmp, bytes);
        fs.renameSync(tmp, this.dbPath);
    }
    sizeBytes() {
        try {
            return fs.statSync(this.dbPath).size;
        }
        catch {
            return this.db.export().length;
        }
    }
    overTenGb() {
        return this.sizeBytes() > TEN_GB;
    }
    close() {
        if (this.closed)
            return;
        if (this.flushTimer) {
            clearTimeout(this.flushTimer);
            this.flushTimer = null;
        }
        this.flush();
        this.db.close();
        this.closed = true;
    }
    /* ---------------- sessions ---------------- */
    createSession(id, groupId, groupName, schema) {
        this.db.run('INSERT INTO sessions (id, group_id, group_name, start_utc, status, schema_json) VALUES (?, ?, ?, ?, ?, ?)', [
            id,
            groupId,
            groupName,
            new Date().toISOString(),
            'recording',
            JSON.stringify(schema),
        ]);
        this.scheduleFlush();
    }
    endSession(id) {
        this.db.run("UPDATE sessions SET status='completed', end_utc=? WHERE id=?", [new Date().toISOString(), id]);
        this.scheduleFlush();
    }
    insertSamples(sessionId, rows) {
        if (!rows.length)
            return;
        this.db.run('BEGIN');
        for (const r of rows)
            this.db.run('INSERT INTO samples (session_id, signal_id, t_ms, value) VALUES (?, ?, ?, ?)', [sessionId, r.signalId, r.tMs, r.value]);
        this.db.run('UPDATE sessions SET sample_count = sample_count + ? WHERE id = ?', [rows.length, sessionId]);
        this.db.run('COMMIT');
        this.scheduleFlush();
    }
    insertEvents(sessionId, rows) {
        if (!rows.length)
            return;
        this.db.run('BEGIN');
        for (const r of rows)
            this.db.run('INSERT INTO events (session_id, signal_id, t_ms, kind, value) VALUES (?, ?, ?, ?, ?)', [sessionId, r.signalId, r.tMs, r.kind, r.value]);
        this.db.run('UPDATE sessions SET event_count = event_count + ? WHERE id = ?', [rows.length, sessionId]);
        this.db.run('COMMIT');
        this.scheduleFlush();
    }
    insertRawComm(sessionId, tMs, direction, hex) {
        this.db.run('INSERT INTO raw_comm (session_id, t_ms, direction, hex) VALUES (?, ?, ?, ?)', [sessionId, tMs, direction, hex]);
        this.scheduleFlush();
    }
    query(sql, params = []) {
        const stmt = this.db.prepare(sql);
        stmt.bind(params);
        const out = [];
        while (stmt.step())
            out.push(stmt.getAsObject());
        stmt.free();
        return out;
    }
    listSessions() {
        return this.query('SELECT * FROM sessions ORDER BY start_utc DESC').map((r) => ({
            id: r.id,
            groupId: r.group_id,
            groupName: r.group_name,
            startUtc: r.start_utc,
            endUtc: r.end_utc ?? null,
            status: r.status,
            signalCount: JSON.parse(r.schema_json).length,
            sampleCount: r.sample_count,
            eventCount: r.event_count,
            sizeBytes: 0,
        }));
    }
    getSession(id) {
        const row = this.query('SELECT * FROM sessions WHERE id = ?', [id])[0];
        if (!row)
            return null;
        return {
            id: row.id,
            groupId: row.group_id,
            groupName: row.group_name,
            startUtc: row.start_utc,
            endUtc: row.end_utc ?? null,
            status: row.status,
            signalCount: JSON.parse(row.schema_json).length,
            sampleCount: row.sample_count,
            eventCount: row.event_count,
            sizeBytes: this.sizeBytes(),
            schema: JSON.parse(row.schema_json),
        };
    }
    readSamples(sessionId, signalId) {
        const rows = signalId
            ? this.query('SELECT signal_id, t_ms, value FROM samples WHERE session_id=? AND signal_id=? ORDER BY t_ms', [sessionId, signalId])
            : this.query('SELECT signal_id, t_ms, value FROM samples WHERE session_id=? ORDER BY t_ms', [sessionId]);
        return rows.map((r) => ({ signalId: r.signal_id, tMs: r.t_ms, value: r.value }));
    }
    readEvents(sessionId) {
        return this.query('SELECT signal_id, t_ms, kind, value FROM events WHERE session_id=? ORDER BY t_ms', [sessionId]).map((r) => ({
            signalId: r.signal_id,
            tMs: r.t_ms,
            kind: r.kind,
            value: r.value,
        }));
    }
    readRawComm(sessionId) {
        return this.query('SELECT t_ms, direction, hex FROM raw_comm WHERE session_id=? ORDER BY t_ms', [sessionId]).map((r) => ({
            tMs: r.t_ms,
            direction: r.direction,
            hex: r.hex,
        }));
    }
}
